# General Science: physics to class 10 level (motion, force and laws of motion,
# gravitation, work, energy and power, pressure, sound, light, electricity and the
# magnetic effects of current). Key first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Motion", "A body starts from rest and moves with a uniform acceleration of 2 m/s². How far does it travel in 5 seconds?",
      ["25 m", "10 m", "20 m", "50 m"],
      "s = ut + ½at² = 0 + ½ × 2 × 5² = 25 m. 10 m is its final velocity (in m/s), not the distance."),
    S(1, 2, "Motion", "A stone dropped from the top of a building reaches the ground in 3 seconds. How tall is the building? (Take g = 10 m/s².)",
      ["45 m", "15 m", "30 m", "90 m"],
      "h = ½gt² = ½ × 10 × 3² = 45 m. 30 m is the speed (in m/s) with which it hits the ground."),
    S(1, 1, "Floatation", "According to Archimedes' principle, the upthrust on a body immersed in a liquid is equal to:",
      ["The weight of the liquid it displaces", "The weight of the body measured in air", "The volume of the body itself", "The density of the liquid used"],
      "A body in a liquid is pushed up by a force equal to the weight of the liquid it pushes aside. A body floats when this upthrust can equal its own weight."),
    S(1, 2, "Electric power", "A 100 W bulb is lit for 5 hours a day for 30 days. How many units (kWh) of electricity does it use?",
      ["15 units", "1.5 units", "3 units", "150 units"],
      "Energy = power × time = 0.1 kW × 5 h × 30 = 15 kWh. One unit on an electricity bill is 1 kWh."),
    S(1, 2, "Resistance", "Two wires of the same material and the same length differ only in thickness: one has twice the diameter of the other. The thicker wire's resistance is:",
      ["One-fourth that of the thinner wire", "Half that of the thinner wire", "Twice that of the thinner wire", "Four times that of the thinner wire"],
      "R = ρL/A, and the cross-sectional area grows as the square of the diameter. Twice the diameter gives four times the area, so the thicker wire has one-fourth the resistance. Half would be true only if area grew in step with diameter."),
    S(1, 2, "Magnetic effects of current", "Which rule gives the direction of the current induced in a conductor that moves in a magnetic field?",
      ["Fleming's right-hand rule", "Fleming's left-hand rule", "Right-hand thumb rule", "Maxwell's right-hand grip rule"],
      "In Fleming's right-hand rule the forefinger points along the field, the thumb along the motion and the middle finger gives the induced current. This is the generator rule; the left-hand rule gives the force on a current in a motor."),
    S(1, 3, "Lenses", "An object is placed 30 cm in front of a convex lens of focal length 20 cm. Where is the image formed?",
      ["60 cm behind the lens", "12 cm behind the lens", "10 cm in front of the lens", "50 cm behind the lens"],
      "Lens formula 1/v − 1/u = 1/f with u = −30 cm, f = +20 cm: 1/v = 1/20 − 1/30 = 1/60, so v = +60 cm, a real image on the other side of the lens."),
    S(1, 2, "Sound", "A girl shouts near a cliff and hears the echo 3 seconds later. If sound travels at 330 m/s, how far away is the cliff?",
      ["495 m", "110 m", "165 m", "990 m"],
      "In 3 s the sound travels 330 × 3 = 990 m, but that is there and back. The cliff is half of that, 495 m away."),
    S(1, 1, "Pressure", "A force of 500 N acts on an area of 0.25 m². What pressure does it produce?",
      ["2,000 Pa", "125 Pa", "500 Pa", "1,000 Pa"],
      "Pressure = force / area = 500 / 0.25 = 2,000 Pa (N/m²). Multiplying instead of dividing gives 125."),

    # ---------- Practice Test 2 ----------
    S(2, 2, "Motion", "A train running at 72 km/h is brought to rest in 40 seconds with uniform retardation. What is the retardation?",
      ["0.5 m/s²", "0.25 m/s²", "1.8 m/s²", "2 m/s²"],
      "72 km/h = 20 m/s. Retardation = change in velocity / time = 20 / 40 = 0.5 m/s². 1.8 comes from forgetting to convert km/h to m/s."),
    S(2, 1, "Laws of motion", "What force is needed to give a car of mass 1,500 kg an acceleration of 2 m/s²?",
      ["3,000 N", "750 N", "1,500 N", "2,000 N"],
      "Newton's second law: F = ma = 1,500 × 2 = 3,000 N."),
    S(2, 2, "Gravitation", "If the distance between two bodies is doubled, the gravitational force between them becomes:",
      ["One quarter", "Half", "Double", "Four times"],
      "Gravitational force varies as 1/r². Doubling r divides the force by 2² = 4."),
    S(2, 1, "Gravitation", "A body weighs 120 N on the Earth. About how much will it weigh on the Moon?",
      ["20 N", "60 N", "120 N", "720 N"],
      "The Moon's gravity is about one-sixth of the Earth's, so the weight becomes about 120 / 6 = 20 N. Its mass does not change; only the pull of gravity on it does."),
    S(2, 2, "Electric power", "A 60 W bulb and a 100 W bulb, both rated for 220 V, are connected in parallel across a 220 V supply. Which glows more brightly?",
      ["The 100 W bulb", "The 60 W bulb", "Both glow equally", "Neither bulb glows"],
      "In parallel each bulb gets its full rated 220 V, so each gives its rated power and the 100 W bulb is brighter. (In series the order reverses, because the 60 W bulb has the higher resistance.)"),
    S(2, 3, "Resistance", "A 4 Ω resistor is connected in series with two 10 Ω resistors that are joined in parallel. What is the total resistance?",
      ["9 Ω", "4.5 Ω", "14 Ω", "24 Ω"],
      "Two equal 10 Ω resistors in parallel give 10/2 = 5 Ω. Adding the 4 Ω in series: 4 + 5 = 9 Ω. 24 Ω treats all three as in series."),
    S(2, 2, "Electromagnetic induction", "An electric generator works on the principle of:",
      ["Electromagnetic induction", "Heating effect of current", "Chemical effect of current", "Total internal reflection"],
      "In a generator a coil rotates in a magnetic field; the changing magnetic field through the coil induces a current (Faraday's electromagnetic induction)."),
    S(2, 2, "Light", "The brilliant sparkle of a cut diamond is mainly due to:",
      ["Total internal reflection", "Dispersion of light only", "Reflection from a mirror", "Interference of light"],
      "Diamond has a very high refractive index and so a small critical angle (about 24°). Light entering it is reflected many times inside before it escapes, which makes it sparkle."),
    S(2, 3, "Heat", "How much heat is needed to raise the temperature of 0.5 kg of water by 20 °C? (Specific heat capacity of water = 4,200 J/kg °C.)",
      ["42,000 J", "4,200 J", "21,000 J", "84,000 J"],
      "Heat = mass × specific heat × rise in temperature = 0.5 × 4,200 × 20 = 42,000 J."),

    # ---------- Drill only ----------
    S(0, 2, "Work and energy", "If the mass of a moving body is doubled and its speed is halved, its kinetic energy becomes:",
      ["Half", "The same", "Twice", "One quarter"],
      "KE = ½mv². Doubling m doubles KE, and halving v divides v² by 4, so the new KE is 2/4 = half the old value."),
    S(0, 2, "Power", "A crane lifts a load of 500 kg through a height of 12 m in 20 seconds. What power does it develop? (Take g = 10 m/s².)",
      ["3,000 W", "300 W", "6,000 W", "30,000 W"],
      "Work = mgh = 500 × 10 × 12 = 60,000 J. Power = work / time = 60,000 / 20 = 3,000 W."),
    S(0, 1, "Waves", "A sound wave travels at 330 m/s with a frequency of 110 Hz. What is its wavelength?",
      ["3 m", "0.33 m", "220 m", "440 m"],
      "Wave speed = frequency × wavelength, so wavelength = 330 / 110 = 3 m."),
    S(0, 2, "Magnetic effects of current", "What is the magnetic field inside a long current-carrying solenoid like?",
      ["Nearly uniform", "Zero everywhere", "Strongest at the ends", "Circular around the axis"],
      "Inside a long solenoid the field lines are parallel straight lines, so the field is nearly uniform. This is used to make electromagnets."),
    S(0, 1, "Electric circuits", "How is a voltmeter connected to measure the potential difference across a resistor?",
      ["In parallel with it", "In series with it", "Across the battery only", "Either way, it makes no difference"],
      "A voltmeter compares the potential at two points, so it is joined across (in parallel with) the resistor. An ammeter goes in series."),
    S(0, 2, "Mirrors", "Where should an object be placed in front of a concave mirror to get its image at infinity?",
      ["At the principal focus", "At the centre of curvature", "Between the focus and the pole", "Beyond the centre of curvature"],
      "Rays from an object at F leave the mirror parallel, so the image is at infinity. This is how a torch or a headlight sends out a beam."),
    S(0, 1, "Electric current", "A current of 2 A flows through a wire for 1 minute. How much charge passes through it?",
      ["120 C", "2 C", "30 C", "60 C"],
      "Charge = current × time = 2 A × 60 s = 120 C. The time must be in seconds."),
    S(0, 2, "Pressure", "Why does a sharp knife cut more easily than a blunt one, for the same push?",
      ["A smaller area gives a greater pressure", "Its edge applies more force for the same push", "A sharp knife weighs more than a blunt knife", "A blunt edge produces more friction on food"],
      "Pressure = force / area. The thin edge of a sharp knife has a very small area, so the same force gives a much greater pressure. The force itself does not change."),
]
